<?php  
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';require_admin();  
$delivered=(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE status='DELIVERED'")->fetchColumn();$open=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status NOT IN ('DELIVERED','CANCELLED')")->fetchColumn();$aov=(float)$pdo->query("SELECT COALESCE(AVG(total_amount),0) FROM orders WHERE status='DELIVERED'")->fetchColumn();$items=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM order_items oi JOIN orders o ON o.order_id=oi.order_id WHERE o.status='DELIVERED'")->fetchColumn();$top=$pdo->query("SELECT p.product_name,SUM(oi.quantity) units,SUM(oi.quantity*oi.unit_price) revenue FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id WHERE o.status='DELIVERED' GROUP BY p.product_id,p.product_name ORDER BY units DESC LIMIT 10")->fetchAll();$recent=$pdo->query("SELECT DATE(created_at) day,COUNT(*) orders,COALESCE(SUM(total_amount),0) sales FROM orders WHERE status='DELIVERED' GROUP BY DATE(created_at) ORDER BY day DESC LIMIT 14")->fetchAll();$title='Reports';require __DIR__.'/../includes/header.php';  
?><section class="shell admin-page"><div class="admin-top"><div><span class="eyebrow">BUSINESS INTELLIGENCE</span><h1>Reports & performance</h1><p>Quick management insight into sales, orders and product performance.</p></div><a class="btn btn-outline" href="/admin/dashboard.php">Dashboard</a></div><div class="admin-stats"><div><span>Delivered sales</span><strong><?=money($delivered)?></strong><small>Completed orders</small></div><div><span>Open orders</span><strong><?=$open?></strong><small>Needs action</small></div><div><span>Average order</span><strong><?=money($aov)?></strong><small>Delivered orders</small></div><div><span>Units sold</span><strong><?=$items?></strong><small>Delivered orders</small></div></div><div class="admin-columns"><div class="panel"><div class="panel-title"><h2>Top products</h2></div><div class="table-wrap"><table class="pro-table"><tr><th>Product</th><th>Units</th><th>Revenue</th></tr><?php foreach($top as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=$r['units']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach;?></table></div></div><div class="panel"><div class="panel-title"><h2>Recent delivered sales</h2></div><div class="table-wrap"><table class="pro-table"><tr><th>Date</th><th>Orders</th><th>Sales</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['day'])?></td><td><?=$r['orders']?></td><td><?=money($r['sales'])?></td></tr><?php endforeach;?></table></div></div></div></section><?php require __DIR__.'/../includes/footer.php';?>